import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    s = input[1]
    t = input[2]

    if sorted(s) != sorted(t):
        print(-1)
        return

    count_s = [0] * (n + 1)
    count_t = [0] * (n + 1)

    for i in range(n):
        count_s[i + 1] = count_s[i] + (s[i] == '1')
        count_t[i + 1] = count_t[i] + (t[i] == '1')

    queue = deque()
    result = 0

    for i in range(n):
        if s[i] == '0' and t[i] == '1':
            queue.append(i)
        elif s[i] == '1' and t[i] == '0':
            if not queue:
                result += 1
            else:
                queue.popleft()

    print(result)

if __name__ == "__main__":
    main()
